{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if set(case) - {"threshold", "calls", "_case_nonce"}:
        raise ValueError("case contains unsupported fields")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("missing required field")

    threshold = case["threshold"]
    calls = case["calls"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    threshold = float(threshold)
    if not math.isfinite(threshold) or threshold < 0:
        raise ValueError("threshold must be a finite non-negative number")
    if not isinstance(calls, list) or not calls:
        raise ValueError("calls must be a non-empty list")

    required = {
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    }
    seen_ids = set()
    prepared = []
    total_tokens = 0

    for index, call in enumerate(calls):
        if not isinstance(call, dict) or set(call) != required:
            raise ValueError("each call must contain exactly the required fields")
        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id or call_id in seen_ids:
            raise ValueError("call_id values must be unique non-empty strings")
        seen_ids.add(call_id)

        values = (call["loss_without_call"], call["loss_with_call"])
        if any(isinstance(value, bool) or not isinstance(value, (int, float)) for value in values):
            raise ValueError("losses must be numeric")
        loss_without = float(values[0])
        loss_with = float(values[1])
        if not math.isfinite(loss_without) or not math.isfinite(loss_with):
            raise ValueError("losses must be finite")

        tokens = call["prediction_tokens"]
        if isinstance(tokens, bool) or not isinstance(tokens, int) or tokens < 0:
            raise ValueError("prediction_tokens must be a non-negative integer")
        if not isinstance(call["parseable"], bool):
            raise ValueError("parseable must be boolean")

        total_tokens += tokens
        prepared.append((index, call_id, loss_without, loss_with, tokens, call["parseable"]))

    if total_tokens <= 0:
        raise ValueError("total prediction_tokens must be positive")

    accepted_call_ids = []
    diagnostics = []
    for index, call_id, loss_without, loss_with, tokens, parseable in prepared:
        normalized_weight = tokens / total_tokens
        weighted_loss_without = loss_without * normalized_weight
        weighted_loss_with = loss_with * normalized_weight
        gain = loss_without - loss_with
        normalized_gain = gain / max(1, tokens)
        stronger_counterfactual = "without_call" if loss_without >= loss_with else "with_call"
        meets_threshold = normalized_gain >= threshold
        accepted = parseable and meets_threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            "call_id": call_id,
            "normalized_weight": round(normalized_weight, 6),
            "weighted_loss_without_call": round(weighted_loss_without, 6),
            "weighted_loss_with_call": round(weighted_loss_with, 6),
            "gain": round(gain, 6),
            "normalized_gain": round(normalized_gain, 6),
            "stronger_counterfactual": stronger_counterfactual,
            "parseable": parseable,
            "meets_threshold": meets_threshold,
            "accepted": accepted,
        })

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
"}
